function manualRoleOf(s) {
  if (!s) return 't';
  if (s.role === 'intern') return 'i'; // 2.02.1: นักศึกษาฝึกสอน
  if (s.role === 'executive') return 'e';
  if (s.role === 'admin') return s.hasHub ? 's' : 'a';
  return 't';
}
